To restrict access to certain endpoints in an Express.js application based on user roles, you can use middleware functions to check the user's role before allowing access. Here's a practical example:

### Steps:
1. **Store user role information** (e.g., in a JWT payload or session).
2. **Create middleware functions** for each role-based restriction.
3. **Apply middleware to routes** as needed.

---

#### Example

Assume we have three roles: `admin`, `user`, and `guest`.

```javascript
// app.js

const express = require('express');
const app = express();

// Mock function to get user role from request (use JWT, session, etc. in production)
function getUserRole(req, res, next) {
  // Example: parse token from Authorization header
  // For this example, we'll just return a hardcoded role for demo
  return next(req.userRole || 'guest');
}

// Middleware to check role
function requireRole(...allowedRoles) {
  return (req, res, next) => {
    const userRole = getUserRole(req, res, next);

    // Note: In real apps, call getUserRole once and pass the result
    // This simple version calls it multiple times for clarity; optimize as needed
    userRole = req.userRole;

    if (!allowedRoles.includes(userRole)) {
      return res.status(403).json({ error: 'Access denied: insufficient role' });
    }

    next();
  };
}

// Example: Only admins can access this route
app.post('/api/admin-action', requireRole('admin'), (req, res) => {
  res.json({ message: 'Admin action performed' });
});

// Users and admins can access this
app.get('/api/user-action', requireRole('user', 'admin'), (req, res) => {
  res.json({ message: 'User action performed' });
});

// Everyone can access this
app.get('/api/public-info', (req, res) => {
  res.json({ message: 'Public info' });
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

---

#### Notes & Best Practices

- Replace the mock `getUserRole` with your actual authentication flow (e.g., decode a JWT, check session data).
- For scalability, consider a single call to `getUserRole` and store the result on `req.userRole` before routing.
- Use HTTP status `403` for forbidden accesses and a clear error message.
- You can extend this pattern with claims from JWTs, e.g. `req.user.role`.

---

This approach is clear, flexible, and easy to test. Let me know if you need a version integrated with JWTs or sessions!
